// Numenor: entry point for numenor.html. Fan work from Tolkien, whose world belongs to the Tolkien Estate; nothing
// from any book, film or game is used. The land is generated by tools/make-numenor.py from the published geography
// and every shape is this project's own. The whole island at true proportion, on the same engine as Mordor.
import {report,LOAD,configureLoading,installErrorHandlers} from '../core/diag.js';
import {boot} from '../core/shell.js';
import {build} from '../engine/build.js';
import {landmarks} from './landmarks.js';
import {nature} from './nature.js';
import {life} from './life.js';
installErrorHandlers();window.LOAD=LOAD;
configureLoading({
  lines:[
    'Fan work. Tolkien\'s world belongs to the Tolkien Estate; nothing from any book, film or game is used.',
    'The island is a star of five points: Mittalmar in the middle, four hundred kilometres across, and a promontory off each point.',
    'Nothing was built on the summit of the Meneltarma. It was the Hallow, open to the sky.',
    'The road up the mountain goes round it three and a half times before it reaches the top.',
    'Hyarrostar grew the timber the shipwrights built with. Its forests come down to the sea.',
    'The Nisimaldar round Eldanna are evergreen, and the trees in them came over the sea from the West.',
    'Nimloth, the White Tree, flowers in the King\'s court in Armenelos. Its scent is strongest at dusk.',
    'The Meneltarma\'s height is ours: no figure is given for it.',
    'Rómenna faces east, toward Middle-earth. Andúnië faces west, toward a land that cannot be seen from it.',
    'A ship is forty metres long and the island seven hundred kilometres across, so the ships are grown with distance to stay in sight.',
    'The eagles on the Meneltarma keep watch. They circle it very slowly, very high.',
  ],
  prefix:'raising Númenor… ',labels:{'map-data':'reading the land',ground:'raising the island',buildings:'building the towns',details:'',landmarks:'planting the White Tree',el:'',traffic:'',nature:'growing the forests',life:'putting out the ships',ui:'opening the windows'}});
// the land cover, the rivers and the coast are not map data the engine reads, so they come in their own file,
// fetched before the build so that the extras can use them synchronously like everything else
const ctx=window._iz={defaultCity:'numenor',models:[landmarks],extras:[{name:'nature',fn:nature},{name:'life',fn:life}]};
boot(()=>fetch('data/cities/numenor-land.json').then(r=>{if(!r.ok)throw new Error('numenor-land.json: HTTP '+r.status);return r.json();})
  .then(land=>{ctx.nmLand=land;},e=>report('land',e))
  .then(()=>build(ctx)));
